contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        // Fresh c: caller's recorded balance is 0, and MinSum defaults to 1 ether > 0,
        // so balances[msg.sender] < MinSum for any non-reverting setup.
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect{value: 0}(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && c.balances(address(this)) == balBefore && address(c).balance == ethBefore);
    }

    receive() external payable {}
}

